export const getCountryTheme = (codeOrName?: string | null): CountryTheme => {
  if (!codeOrName) return COUNTRY_THEMES.IN;
  const upper = codeOrName.trim().toUpperCase();
  if (COUNTRY_THEMES[upper]) {
    return COUNTRY_THEMES[upper];
  }
  const slug = codeOrName
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  const found = Object.values(COUNTRY_THEMES).find(
    (t) => t.slug === slug || t.name.toLowerCase() === codeOrName.trim().toLowerCase()
  );
  return found || COUNTRY_THEMES.IN;
};
